CREATE POLICY "kb_images_select_own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'kb-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "kb_images_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'kb-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "kb_images_update_own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'kb-images' AND auth.uid()::text = (storage.foldername(name))[1]) WITH CHECK (bucket_id = 'kb-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "kb_images_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'kb-images' AND auth.uid()::text = (storage.foldername(name))[1]);